// The extension's adapter over the family hotkey scheme.
//
// The scheme is NOT defined here. It is the one table both ChatGoose clients
// run — the hub's packages/chatgoose-hotkeys (its README is the spec), vendored
// as `@chatgoose/hotkeys` under vendor/chatgoose-hotkeys (generated by the hub's
// scripts/vendor-hotkeys.mjs, never hand-edited). A key therefore means the
// same thing here and in the OnlyFans desktop app:
//
// - everything that writes into the reply field, plus Cancel — ⌘+key on macOS,
//   Ctrl+key on Windows (E Reply, I Fix, G Hi, P Ping, . Cancel);
// - analysis, panels and toggles — ⌘⇧+key on macOS, Ctrl+Alt+key on Windows
//   (H Help, S Recap, O tone, B Review, L Split, M Spenders, C Coach,
//   K fan notes).
//
// Keys are matched by physical position (`event.code`), so the Russian layout
// works without switching. Facts behind the choices, from Firefox's
// browser-sets.inc.xhtml: among bare accel+letter only N, T, W (and quit) are
// reserved, among accel+shift only P and W; every combo used here can be
// claimed by the page, and a press the page misses opens find, page info, print
// or a sidebar — never a reload (R is unused on purpose; F stays find-in-page).
// Windows cannot use Ctrl+Shift or Alt+Shift: the team switches the input
// language with both.
//
// This module maps the family actions onto the extension's action ids and
// builds every label; content/hotkey-input.ts owns the engine instance.

import {
  detectHotkeyPlatform,
  hotkeyAriaShortcut,
  hotkeyChip,
  hotkeyLabel,
  hotkeysForClient,
  type HotkeyAction as SchemeAction,
  type HotkeyPlatform,
} from '@chatgoose/hotkeys';

import type { FeatureType } from './types.js';

export type LabelPlatform = HotkeyPlatform;

export type HotkeyAction =
  | 'fast-reply'
  | 'improve-draft'
  | 'help-me'
  | 'hi-greeting'
  | 'ping'
  | 'fan-summary'
  | 'coach'
  | 'chat-review'
  | 'cycle-tone'
  | 'toggle-split'
  | 'cancel'
  | 'spenders-board'
  | 'fan-notes'
  | 'cheatsheet';

/** Every action of the family table, as the extension names it. */
export type SchemeHotkeyAction = Exclude<HotkeyAction, 'cheatsheet'>;

/** Family action → extension action. TOTAL: a new family action fails
 * typecheck until the extension places it. */
export const EXTENSION_ACTION: Record<SchemeAction, SchemeHotkeyAction> = {
  reply: 'fast-reply',
  fix: 'improve-draft',
  hi: 'hi-greeting',
  ping: 'ping',
  cancel: 'cancel',
  help: 'help-me',
  recap: 'fan-summary',
  tone: 'cycle-tone',
  review: 'chat-review',
  split: 'toggle-split',
  spenders: 'spenders-board',
  coach: 'coach',
  notes: 'fan-notes',
};

const SCHEME_ACTION = Object.fromEntries(
  Object.entries(EXTENSION_ACTION).map(([scheme, extension]) => [extension, scheme]),
) as Record<SchemeHotkeyAction, SchemeAction>;

/**
 * Most AI feature actions map 1:1 to a FeatureType; the rest are app actions.
 * `help-me` stays mapped so the Help button and H key share one discoverable
 * identity, but dispatch reroutes it to Coach's situation preset (E79).
 * `coach` and `fan-summary` are APP actions (not entries here): Coach opens the
 * Coach chat and Recap opens the recap picker; neither starts a generation
 * directly. `dispatchHotkey` routes anything absent from this map as an app
 * action.
 */
export const HOTKEY_FEATURE: Partial<Record<HotkeyAction, FeatureType>> = {
  'fast-reply': 'fast-reply',
  'improve-draft': 'improve-draft',
  'help-me': 'help-me',
  'hi-greeting': 'hi-greeting',
  ping: 'ping',
  'chat-review': 'chat-review',
};

/**
 * Russian names for the hotkey actions, shared by the in-page cheatsheet and the
 * Options «Хоткеи» pane. Typed as a TOTAL record on purpose: a new
 * `HotkeyAction` fails `pnpm typecheck` until it is named here.
 */
export const HOTKEY_ACTION_NAMES: Record<HotkeyAction, string> = {
  'fast-reply': 'Reply — ответ фану',
  'improve-draft': 'Fix — исправить черновик',
  'hi-greeting': 'Hi — приветствие',
  ping: 'Ping — вернуть молчащего фана',
  cancel: 'Отменить генерацию',
  'help-me': 'Help — разбор ситуации в Coach',
  'fan-summary': 'Recap — выбор сводки по фану',
  'cycle-tone': 'Сменить тон (Casual / Flirt / Sell / Spice)',
  'chat-review': 'Review — оценка чата',
  'toggle-split': 'Split — Reply и Fix серией из 2–3 сообщений',
  'spenders-board': 'Доска Spenders',
  coach: 'Coach — спросить AI про фана',
  'fan-notes': 'Заметки о фане (заметки Fansly)',
  cheatsheet: 'Шпаргалка хоткеев',
};

export function detectLabelPlatform(): LabelPlatform {
  const platform =
    (typeof navigator !== 'undefined' &&
      (navigator.platform || navigator.userAgent)) ||
    '';
  return detectHotkeyPlatform(platform);
}

/** '⌘E' / 'Ctrl+E', '⌘⇧H' / 'Ctrl+Alt+H'; the cheatsheet is the bare '?'. */
export function hotkeyComboLabel(action: HotkeyAction, platform: LabelPlatform): string {
  return action === 'cheatsheet' ? '?' : hotkeyLabel(SCHEME_ACTION[action], platform);
}

/** The aria-keyshortcuts value for an action ('Meta+E', 'Control+Alt+L'). */
export function hotkeyAriaLabel(action: SchemeHotkeyAction, platform: LabelPlatform): string {
  return hotkeyAriaShortcut(SCHEME_ACTION[action], platform);
}

/**
 * The hotkey label parts for an AI feature button (the toolbar's
 * Reply/Fix/Hi/Ping/Review), or null when the feature has no bound key.
 * `full` is the platform combo for tooltips and the cheatsheet; `short` is the
 * compact chip — the bare letter for the text actions (they share one
 * modifier), '⇧B' / 'Alt+B' for a panel action; `aria` is the
 * aria-keyshortcuts value. Sourced from the family table,
 * so chips can never drift from the live bindings.
 */
export function featureHotkeyLabel(
  feature: FeatureType,
  platform: LabelPlatform,
): { full: string; short: string; aria: string } | null {
  for (const [action, mapped] of Object.entries(HOTKEY_FEATURE) as Array<[HotkeyAction, FeatureType]>) {
    if (mapped === feature && action !== 'cheatsheet') {
      const scheme = SCHEME_ACTION[action];
      return {
        full: hotkeyLabel(scheme, platform),
        short: hotkeyChip(scheme, platform),
        aria: hotkeyAriaShortcut(scheme, platform),
      };
    }
  }
  return null;
}

/** The semantic groups of the cheatsheet and the Options pane. */
export type HotkeyGroup = 'text' | 'panel' | 'reference' | 'differs';

export interface HotkeyEntry {
  /** Stable row id: the action id, or a name for a row handled outside the
   * family table ('insert-part', 'close', 'send', 'navigation'). */
  id: string;
  /** The action, or null for a row handled outside the family table. */
  action: HotkeyAction | null;
  /** The key(s) as displayed: '⌘E' / 'Ctrl+Alt+H' / '?' / 'Enter'. */
  keys: string;
  /** Russian description of what the key does. */
  name: string;
  group: HotkeyGroup;
}

/** Every reference row for this platform, in display order within each group:
 * the family table (the rows the Fansly extension runs), the `?` cheatsheet, the keys the
 * extension handles outside the table, and what works differently than in the
 * desktop app. Pure — both surfaces render exactly this list. */
export function buildHotkeyEntries(platform: LabelPlatform): HotkeyEntry[] {
  const entries: HotkeyEntry[] = [];
  for (const def of hotkeysForClient('fansly')) {
    const action = EXTENSION_ACTION[def.action];
    entries.push({
      id: action,
      action,
      keys: hotkeyLabel(def.action, platform),
      name: HOTKEY_ACTION_NAMES[action],
      group: def.level === 'text' ? 'text' : 'panel',
    });
  }
  entries.push(
    { id: 'insert-part', action: null, keys: 'Enter', name: 'Вставить следующую часть показанного ответа', group: 'text' },
    { id: 'cheatsheet', action: 'cheatsheet', keys: '?', name: HOTKEY_ACTION_NAMES.cheatsheet, group: 'reference' },
    { id: 'close', action: null, keys: 'Esc', name: 'Закрыть оверлей, доску или шпаргалку', group: 'reference' },
    {
      id: 'send',
      action: null,
      keys: 'Enter',
      name: 'Отправка — это Enter самого Fansly (в приложении для OnlyFans отправка другая)',
      group: 'differs',
    },
    {
      id: 'navigation',
      action: null,
      keys: platform === 'mac' ? '⌘K ⌘U' : 'Ctrl+K Ctrl+U',
      name: 'Переход по чатам и палитра — только в приложении для OnlyFans',
      group: 'differs',
    },
  );
  return entries;
}

/** macOS: the pre-2.5 ⌘⇧ habits that still mean the same action. */
export const MAC_LEGACY_NOTE = 'На Mac ⌘⇧E, ⌘⇧I и ⌘⇧G тоже работают — как ⌘E, ⌘I и ⌘G.';
